import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.Ddyno5UB.js";const u=JSON.parse('{"title":"Routes and Networking","description":"","frontmatter":{},"headers":[],"relativePath":"openshift/4-routes-and-networking.md","filePath":"openshift/4-routes-and-networking.md"}'),n={name:"openshift/4-routes-and-networking.md"};function r(o,e,h,p,l,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="routes-and-networking" tabindex="-1">Routes and Networking <a class="header-anchor" href="#routes-and-networking" aria-label="Permalink to &quot;Routes and Networking&quot;">​</a></h1><p>In standard Kubernetes, you expose services to the internet using an <code>Ingress</code> object. While OpenShift <em>supports</em> standard Ingress objects for backwards compatibility, its native and preferred method for external routing is the <strong>Route</strong> object.</p><h2 id="openshift-routes-vs-kubernetes-ingress" tabindex="-1">OpenShift Routes vs Kubernetes Ingress <a class="header-anchor" href="#openshift-routes-vs-kubernetes-ingress" aria-label="Permalink to &quot;OpenShift Routes vs Kubernetes Ingress&quot;">​</a></h2><p>Routes existed in OpenShift long before the K8s community standardized the Ingress object. A Route is processed by the <strong>OpenShift Router</strong> (which is essentially an HAProxy load balancer running as pods inside the cluster).</p><p>Routes are generally easier to configure than Ingress objects and offer native TLS termination strategies out of the box.</p><h3 id="exposing-a-service" tabindex="-1">Exposing a Service <a class="header-anchor" href="#exposing-a-service" aria-label="Permalink to &quot;Exposing a Service&quot;">​</a></h3><p>The fastest way to generate a Route and expose an internal service to the public internet is using the <code>oc expose</code> command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Assuming you have a Service named &#39;frontend&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svc/frontend</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View the generated URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span></span></code></pre></div><p>By default, OpenShift will automatically generate a DNS hostname for your route based on the service name, project name, and the cluster&#39;s base domain (e.g., <code>frontend-myproject.apps.cluster.example.com</code>).</p><h3 id="specifying-a-custom-hostname" tabindex="-1">Specifying a Custom Hostname <a class="header-anchor" href="#specifying-a-custom-hostname" aria-label="Permalink to &quot;Specifying a Custom Hostname&quot;">​</a></h3><p>If you want to use a specific domain name, you can pass it to the expose command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svc/frontend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hostname=www.mycompany.com</span></span></code></pre></div><h2 id="tls-termination-strategies" tabindex="-1">TLS Termination Strategies <a class="header-anchor" href="#tls-termination-strategies" aria-label="Permalink to &quot;TLS Termination Strategies&quot;">​</a></h2><p>Securing your routes with HTTPS is handled entirely by the HAProxy router. OpenShift supports three distinct TLS termination strategies:</p><h3 id="_1-edge-termination" tabindex="-1">1. Edge Termination <a class="header-anchor" href="#_1-edge-termination" aria-label="Permalink to &quot;1. Edge Termination&quot;">​</a></h3><p>The TLS connection is terminated at the OpenShift Router. The traffic from the client to the router is encrypted (HTTPS), but the traffic from the router to your actual pod is unencrypted (HTTP).</p><ul><li><strong>Use case:</strong> Standard web applications where internal cluster traffic is trusted.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edge</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service=frontend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hostname=www.example.com</span></span></code></pre></div><h3 id="_2-passthrough-termination" tabindex="-1">2. Passthrough Termination <a class="header-anchor" href="#_2-passthrough-termination" aria-label="Permalink to &quot;2. Passthrough Termination&quot;">​</a></h3><p>The OpenShift Router does <em>not</em> decrypt the traffic. It simply forwards the encrypted TCP stream directly to your pod. Your pod must have its own SSL certificates mounted to terminate the connection.</p><ul><li><strong>Use case:</strong> Strict security compliance requirements where traffic must remain encrypted until it hits the application code.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passthrough</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service=secure-app</span></span></code></pre></div><h3 id="_3-re-encrypt-termination" tabindex="-1">3. Re-encrypt Termination <a class="header-anchor" href="#_3-re-encrypt-termination" aria-label="Permalink to &quot;3. Re-encrypt Termination&quot;">​</a></h3><p>A hybrid approach. The OpenShift Router terminates the external TLS connection using its public certificate, but then <em>re-encrypts</em> the traffic using an internal cluster certificate before sending it to your pod.</p><ul><li><strong>Use case:</strong> High security requirements without forcing the application developers to manage public SSL certificates inside their containers.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reencrypt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service=secure-app</span></span></code></pre></div>`,26)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
